// Strict validator for decision cards (cards/decision/*.json).
//
// Unlike validate-drills.js this runs AJV in strict mode against the schema
// exactly as generated by the app (no $schema delete, no validateSchema:false),
// with ajv-keywords' uniqueItemProperties for unique option ids.
//
// Fails on: invalid JSON, schema errors, filename !== id, duplicate id across files.
//
// Usage: node scripts/validate-cards.js [--dir <path>]
import { existsSync, readFileSync, readdirSync, statSync } from 'fs';
import { basename, join, resolve } from 'path';
import Ajv2020 from 'ajv/dist/2020.js';
import addKeywords from 'ajv-keywords';

function argValue(name) {
  const i = process.argv.indexOf(name);
  if (i === -1) return undefined;
  const v = process.argv[i + 1];
  if (v === undefined || v.startsWith('--')) {
    console.error(`Missing value for ${name}`);
    process.exit(1);
  }
  return v;
}

const dirArg = argValue('--dir');
const cardsDir = dirArg
  ? resolve(process.cwd(), dirArg)
  : new URL('../cards/decision', import.meta.url).pathname;
const schemaPath = new URL('../docs/schema/card.schema.json', import.meta.url).pathname;

// unicode: false makes maxLength/minLength count UTF-16 code units, matching
// zod's .max()/.min() in the app. AJV's default counts code points, so strings
// with astral-plane characters (most emoji) would pass here and then be dropped
// by the app at runtime.
const ajv = new Ajv2020({
  strict: true,
  allErrors: true,
  unicode: false,
  // AJV flags `unicode` as deprecated but still honours it; silence only that notice.
  logger: {
    log: console.log.bind(console),
    warn: (...args) => {
      if (!String(args[0]).startsWith('DEPRECATED: option unicode')) console.warn(...args);
    },
    error: console.error.bind(console),
  },
});
addKeywords(ajv, ['uniqueItemProperties']);

const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
const validate = ajv.compile(schema);

if (!existsSync(cardsDir) || !statSync(cardsDir).isDirectory()) {
  console.error(`FAIL no cards found in ${cardsDir}`);
  process.exit(1);
}

const files = readdirSync(cardsDir)
  .filter((f) => f.endsWith('.json'))
  .sort();

if (files.length === 0 && !dirArg) {
  console.error(`FAIL no cards found in ${cardsDir}`);
  process.exit(1);
}

let failed = 0;
const seenIds = new Map(); // id -> file

for (const file of files) {
  const filePath = join(cardsDir, file);
  let data;
  try {
    data = JSON.parse(readFileSync(filePath, 'utf8'));
  } catch (e) {
    console.error(`FAIL ${file}: invalid JSON — ${e.message}`);
    failed++;
    continue;
  }

  if (!validate(data)) {
    console.error(`FAIL ${file}:`);
    for (const err of validate.errors) {
      console.error(`  ${err.instancePath || '/'} ${err.message}`);
    }
    failed++;
    continue;
  }

  const expectedId = basename(file, '.json');
  if (data.id !== expectedId) {
    console.error(`FAIL ${file}: id "${data.id}" does not match filename "${expectedId}"`);
    failed++;
    continue;
  }

  if (seenIds.has(data.id)) {
    console.error(`FAIL ${file}: duplicate id "${data.id}" (also in ${seenIds.get(data.id)})`);
    failed++;
    continue;
  }
  seenIds.set(data.id, file);

  console.log(`OK   ${file}`);
}

if (failed > 0) {
  console.error(`\n${failed} file(s) failed validation.`);
  process.exit(1);
}
console.log(`\nAll ${files.length} card(s) valid.`);
